variables.manual_mismatch_zones:
{% set ns = namespace(v=[]) %}
{% for z in ["sklep_michal","prizemi_michal","prizemi_chodba_zachod","1p_jidelna","1p_kuchyn","1p_koupelna","1p_chodba","2p_mama"] %}
  {% set manual = is_state('input_boolean.' ~ z ~ '_manual_override', 'on')
      and (states('input_select.' ~ z ~ '_manual_override_type') == 'Do další změny rozvrhu'
           or (states('input_select.' ~ z ~ '_manual_override_type') == 'Časovač'
               and is_state('timer.' ~ z ~ '_manual_override', 'active'))) %}
  {% set enabled = is_state('input_boolean.schedule_enable_' ~ z, 'on') %}
  {% set actual = state_attr('climate.' ~ z, 'temperature') | float(default=none) %}
  {% set target = states('input_number.' ~ z ~ '_last_comfort') | float(default=none) %}
  {% if manual and enabled and actual is not none and target is not none and ((actual-target)|abs > 0.1) %}
    {% set ns.v = ns.v + [z] %}
  {% endif %}
{% endfor %}
{{ ns.v }}

